  1	import React, { useEffect, useMemo, useState } from 'react';
  2	import CurrentVulnerabilitiesTable from './CurrentVulnerabilitiesTable';
  3	import VulnerabilityStatisticsPage from './statistics/VulnerabilityStatisticsPage';
  4	import VulnerabilityHeatmap from './VulnerabilityHeatmap';
  5	
  6	/**
  7	 * One destination for the vulnerability analysis views that used to be
  8	 * separate entries in the rail (/vulnerabilities/current, /vulnerability-statistics,
  9	 * /vulnerability-heatmap).
 10	 *
 11	 * Those routes still exist and still work — bookmarks, the E2E page sweep and
 12	 * any link already in circulation keep resolving. This page is an additional
 13	 * entry point, not a replacement, which is why nothing was deleted to build it.
 14	 *
 15	 * Only the selected view is mounted. Each of the three fetches its own data on
 16	 * mount, so rendering all three would fire three independent request storms to
 17	 * show one of them.
 18	 */
 19	
 20	type TabId = 'overview' | 'lense' | 'heatmap';
 21	
 22	interface Tab {
 23	  id: TabId;
 24	  label: string;
 25	  /** Where this view lived before, kept as the deep link for anyone who needs just it. */
 26	  standalone: string;
 27	  /**
 28	   * Roles that may see the tab, or undefined when everyone in Vulnerability
 29	   * Management may. These mirror the gates the rail applied before these views
 30	   * were folded together — the controller is still the boundary, this is the UI
 31	   * half of the same rule (CLAUDE.md Principle 2).
 32	   */
 33	  roles?: string[];
 34	}
 35	
 36	const TABS: Tab[] = [
 37	  {
 38	    id: 'overview',
 39	    label: 'Overview',
 40	    standalone: '/vulnerabilities/current',
 41	    roles: ['ADMIN', 'SECCHAMPION', 'VULN'],
 42	  },
 43	  { id: 'lense', label: 'Lense', standalone: '/vulnerability-statistics' },
 44	  { id: 'heatmap', label: 'Heatmap', standalone: '/vulnerability-heatmap' },
 45	];
 46	
 47	const DEFAULT_TAB: TabId = 'overview';
 48	
 49	function isTabId(value: string | null): value is TabId {
 50	  return TABS.some((tab) => tab.id === value);
 51	}
 52	
 53	const AnalyticsTabs: React.FC = () => {
 54	  const [active, setActive] = useState<TabId>(DEFAULT_TAB);
 55	  /*
 56	   * Roles come from window.currentUser, which Layout.astro leaves undefined
 57	   * until its auth fetch resolves and then announces with a `userLoaded` event.
 58	   * Reading it once on mount is a race: this island frequently hydrates first,
 59	   * sees no roles, and hides a tab the user is entitled to — which is exactly
 60	   * what happened before this listener existed. Sidebar.tsx reads roles the
 61	   * same way for the same reason.
 62	   */
 63	  // null means "auth has not resolved yet", which is a different state from
 64	  // "resolved, and this user has no roles" — see the fallback effect below.
 65	  const [roles, setRoles] = useState<string[] | null>(null);
 66	  useEffect(() => {
 67	    const readRoles = () => {
 68	      const user = (window as any).currentUser;
 69	      if (user === undefined) return; // still pending; the event will bring us back
 70	      setRoles((user?.roles as string[]) ?? []);
 71	    };
 72	    readRoles();
 73	    window.addEventListener('userLoaded', readRoles);
 74	    return () => window.removeEventListener('userLoaded', readRoles);
 75	  }, []);
 76	
 77	  const visibleTabs = useMemo(
 78	    () => TABS.filter((tab) => !tab.roles || tab.roles.some((role) => (roles ?? []).includes(role))),
 79	    [roles],
 80	  );
 81	
 82	  // `location` does not exist during Astro's server render, so the tab in the
 83	  // URL is read after mount. Server and client both render the default first,
 84	  // which keeps the island's markup identical on both sides.
 85	  useEffect(() => {
 86	    const requested = new URLSearchParams(window.location.search).get('tab');
 87	    if (isTabId(requested)) setActive(requested);
 88	  }, []);
 89	
 90	  /*
 91	   * If the selected tab is not one this user may see — a stale ?tab= link —
 92	   * fall back to the first tab they can.
 93	   *
 94	   * Deliberately skipped while roles are null. During the pending window every
 95	   * gated tab looks invisible, so running this would silently move an entitled
 96	   * user off their default tab a moment before the roles that justify it arrive.
 97	   */
 98	  useEffect(() => {
 99	    if (roles === null) return;
100	    if (visibleTabs.length > 0 && !visibleTabs.some((tab) => tab.id === active)) {
101	      setActive(visibleTabs[0].id);
102	    }
103	  }, [roles, visibleTabs, active]);
104	
105	  const selectTab = (id: TabId) => {
106	    setActive(id);
107	    // Reflect the choice in the URL so the view can be shared or reloaded,
108	    // without adding a history entry per click.
109	    const url = new URL(window.location.href);
110	    url.searchParams.set('tab', id);
111	    window.history.replaceState({}, '', url);
112	  };
113	
114	  return (
115	    <div
116	      className="container-fluid py-3 d-flex flex-column"
117	      style={{ height: 'calc(100dvh - 9.5rem)', minHeight: 0, overflow: 'hidden' }}
118	    >
119	      <div className="flex-shrink-0">
120	        <p className="scand-label mb-1">Vulnerability Management · Analyze</p>
121	        <h1 className="mb-1">Analytics</h1>
122	        <p className="text-secondary mb-2">
123	          One destination for the analysis views that used to be separate entries in the rail.
124	        </p>
125	
126	        <div className="d-flex flex-wrap align-items-center gap-3 mb-3">
127	          <div className="btn-group" role="tablist" aria-label="Analysis view">
128	            {visibleTabs.map((tab) => {
129	              const selected = tab.id === active;
130	              return (
131	                <button
132	                  key={tab.id}
133	                  type="button"
134	                  role="tab"
135	                  aria-selected={selected}
136	                  className={`btn ${selected ? 'btn-primary' : 'btn-outline-dark'}`}
137	                  onClick={() => selectTab(tab.id)}
138	                >
139	                  {tab.label}
140	                </button>
141	              );
142	            })}
143	          </div>
144	          {visibleTabs.some((tab) => tab.id === active) && (
145	            <a className="small" href={TABS.find((tab) => tab.id === active)!.standalone}>
146	              Open this view on its own page
147	            </a>
148	          )}
149	        </div>
150	      </div>
151	
152	      <div
153	        className={`flex-grow-1 ${active === 'overview' ? '' : 'overflow-auto'}`}
154	        style={{ minHeight: 0 }}
155	      >
156	        {active === 'overview' && <CurrentVulnerabilitiesTable embedded />}
157	        {active === 'lense' && <VulnerabilityStatisticsPage />}
158	        {active === 'heatmap' && <VulnerabilityHeatmap />}
159	      </div>
160	    </div>
161	  );
162	};
163	
164	export default AnalyticsTabs;
