class Severity(StrEnum):
    INFO = "INFO"
    LOW = "LOW"
    MEDIUM = "MEDIUM"
    HIGH = "HIGH"
    CRITICAL = "CRITICAL"


class TargetStatus(StrEnum):
    SUCCESS = "SUCCESS"
    PARTIAL = "PARTIAL"
    FAILED = "FAILED"


def _utc(value: datetime) -> datetime:
    if value.tzinfo is None:
        return value.replace(tzinfo=UTC)
    return value.astimezone(UTC)


def _now() -> datetime:
    return datetime.now(UTC)


@dataclass(frozen=True, slots=True)
class Finding:
    rule_id: str
    external_id: str
    severity: Severity
    confidence: float
    title: str
    description: str
    recommendation: str
    evidence: str
    url: str
    engine: str = "secman-web-check"
    model: str | None = None
    created_at: datetime = field(default_factory=_now)

    def __post_init__(self) -> None:
        object.__setattr__(self, "created_at", _utc(self.created_at))

    @classmethod
    def create(
        cls,
        rule_id: str,
        url: str,
        severity: Severity,
        title: str,
        *,
        confidence: float = 1.0,
        description: str = "",
        recommendation: str = "",
        evidence: str = "",
        engine: str = "secman-web-check",
        model: str | None = None,
        created_at: datetime | None = None,
    ) -> Finding:
        """Create a finding whose external identity is stable for rule and target."""
        identity = sha256(f"{rule_id}\N{UNIT SEPARATOR}{url}".encode()).hexdigest()
        return cls(
            rule_id=rule_id,
            external_id=f"{rule_id}:{identity}",
            severity=severity,
            confidence=confidence,
            title=title,
            description=description,
            recommendation=recommendation,
            evidence=evidence,
            url=url,
            engine=engine,
            model=model,
            created_at=_now() if created_at is None else created_at,
        )


