package com.secman.controller

import com.secman.dto.*
import com.secman.service.*
import io.micronaut.core.annotation.Nullable
import io.micronaut.http.HttpResponse
import io.micronaut.http.annotation.*
import io.micronaut.scheduling.TaskExecutors
import io.micronaut.scheduling.annotation.ExecuteOn
import io.micronaut.security.annotation.Secured
import io.micronaut.security.authentication.Authentication
import io.micronaut.security.rules.SecurityRule

@Controller("/api/integrations/v1")
@Secured(SecurityRule.IS_AUTHENTICATED)
@ExecuteOn(TaskExecutors.BLOCKING)
open class IntegrationController(
    private val admin: IntegrationAdminService,
    private val reads: IntegrationReadService,
    private val scans: IntegrationScanService,
    private val health: IntegrationHealthNotifier
) {
    @Get("/scanners")
    open fun scanners(authentication: Authentication) = reads.scanners(authentication)

    @Post("/scanners")
    @Secured("ADMIN")
    open fun createScanner(@Body request: IntegrationScannerRequest, authentication: Authentication) =
        admin.saveScanner(null, request, authentication)

    @Put("/scanners/{id}")
    @Secured("ADMIN")
    open fun updateScanner(@PathVariable id: Long, @Body request: IntegrationScannerRequest, authentication: Authentication) =
        admin.saveScanner(id, request, authentication)

    @Post("/scanners/{id}/subjects")
    @Secured("ADMIN")
    open fun bind(@PathVariable id: Long, @Body request: IntegrationSubjectRequest, authentication: Authentication) =
        reads.subject(admin.bind(id, request, authentication), authentication)

    @Get("/scanners/{id}/subjects")
    open fun subjects(@PathVariable id: Long, @QueryValue(defaultValue = "0") page: Int,
                      @QueryValue(defaultValue = "100") size: Int, authentication: Authentication) =
        reads.subjects(id, page, size, authentication)

    @Post("/runs")
    open fun submit(@Body request: IntegrationRunRequest, authentication: Authentication) =
        scans.submit(request, authentication).also(health::completed)

    @Get("/summary")
    open fun summary(authentication: Authentication) = reads.summary(authentication)

    @Get("/runs/{id}")
    open fun run(@PathVariable id: Long, authentication: Authentication) = reads.run(id, authentication)

    @Get("/runs")
    open fun runs(@QueryValue(defaultValue = "0") page: Int, @QueryValue(defaultValue = "100") size: Int,
                  @Nullable @QueryValue scannerId: Long?, @Nullable @QueryValue subjectId: Long?, authentication: Authentication) =
        reads.runs(page, size, scannerId, subjectId, authentication)

    @Get("/findings")
    open fun findings(@QueryValue(defaultValue = "0") page: Int, @QueryValue(defaultValue = "100") size: Int,
                      @Nullable @QueryValue scannerId: Long?, @Nullable @QueryValue subjectId: Long?,
                      @Nullable @QueryValue githubRepositoryId: Long?, @Nullable @QueryValue source: String?,
                      @Nullable @QueryValue owner: String?, @Nullable @QueryValue severity: String?,
                      @Nullable @QueryValue state: String?, @Nullable @QueryValue search: String?, authentication: Authentication) =
        reads.findings(page, size, IntegrationFindingFilter(scannerId, subjectId, githubRepositoryId, source, owner, severity, state, search), authentication)

    @Get("/findings/{id}")
    open fun finding(@PathVariable id: Long, authentication: Authentication) = reads.finding(id, authentication)

    @Get("/findings/{id}/attachments/{attachmentId}")
    open fun attachment(@PathVariable id: Long, @PathVariable attachmentId: Long, authentication: Authentication): HttpResponse<ByteArray> {
        val attachment = reads.attachment(id, attachmentId, authentication)
        return HttpResponse.ok(attachment.content).contentType(attachment.contentType)
            .header("X-Content-Type-Options", "nosniff")
            .header("Content-Disposition", "attachment; filename=\"" + attachment.fileName + "\"")
            .header("Cache-Control", "private, no-store")
    }
}
package com.secman.mcp.tools

import com.secman.domain.McpOperation
import com.secman.domain.McpPermission
import com.secman.dto.IntegrationFindingFilter
import com.secman.dto.mcp.McpExecutionContext
import com.secman.repository.UserRepository
import com.secman.service.IntegrationReadService
import io.micronaut.http.exceptions.HttpStatusException
import io.micronaut.security.authentication.Authentication
import jakarta.inject.Singleton

private val emptySchema: Map<String, Any> = mapOf("type" to "object", "properties" to emptyMap<String, Any>())
private val idSchema: Map<String, Any> = mapOf(
    "type" to "object",
    "required" to listOf("id"),
    "properties" to mapOf("id" to mapOf("type" to "integer", "minimum" to 1)),
)
private val pageProperties = mapOf(
    "page" to mapOf("type" to "integer", "minimum" to 0),
    "size" to mapOf("type" to "integer", "minimum" to 1, "maximum" to 100),
)

private fun delegatedAuthentication(users: UserRepository, context: McpExecutionContext): Authentication? {
    val user = users.findById(context.delegatedUserId!!).orElse(null) ?: return null
    return Authentication.build(
        user.username,
        user.roles.map { it.name },
        mapOf("userId" to user.id!!, "email" to user.email),
    )
}

private fun integrationRead(
    users: UserRepository,
    context: McpExecutionContext,
    block: (Authentication) -> Any,
): McpToolResult {
    val auth = delegatedAuthentication(users, context)
        ?: return McpToolResult.error("FORBIDDEN", "Delegated user unavailable")
    return try {
        McpToolResult.success(block(auth))
    } catch (error: HttpStatusException) {
        McpToolResult.error(error.status.name, error.message ?: "Integration read rejected")
    }
}

private fun page(arguments: Map<String, Any>): Pair<Int, Int> =
    ((arguments["page"] as? Number)?.toInt() ?: 0) to
        ((arguments["size"] as? Number)?.toInt() ?: 100)

private fun id(arguments: Map<String, Any>, name: String = "id"): Long? =
    (arguments[name] as? Number)?.toLong()

/** Exposes the aggregate health of integrations visible to the delegated user. */
@Singleton
class GetIntegrationSummaryTool(
    private val reads: IntegrationReadService,
    private val users: UserRepository,
) : McpTool {
    override val name = "get_integration_summary"
    override val description = "Get an asset-scoped health summary across registered security scanners."
    override val operation = McpOperation.READ
    override val inputSchema = emptySchema

    override suspend fun execute(arguments: Map<String, Any>, context: McpExecutionContext): McpToolResult {
        requireDelegation(context)?.let { return it }
        if (!context.hasPermission(McpPermission.INTEGRATIONS_READ))
            return McpToolResult.error("FORBIDDEN", "Integration read permission required")
        return integrationRead(users, context, reads::summary)
    }
}

/** Lists integration findings after applying the delegated user's asset scope. */
@Singleton
class ListIntegrationFindingsTool(
    private val reads: IntegrationReadService,
    private val users: UserRepository,
) : McpTool {
    override val name = "list_integration_findings"
    override val description = "List asset-scoped scanner findings with bounded filters for security-work triage."
    override val operation = McpOperation.READ
    override val inputSchema: Map<String, Any> = mapOf(
        "type" to "object",
        "properties" to pageProperties + mapOf(
            "scannerId" to mapOf("type" to "integer", "minimum" to 1),
            "subjectId" to mapOf("type" to "integer", "minimum" to 1),
            "githubRepositoryId" to mapOf("type" to "integer", "minimum" to 1),
            "source" to mapOf("type" to "string"),
            "owner" to mapOf("type" to "string", "maxLength" to 255),
            "severity" to mapOf("type" to "string", "enum" to listOf("CRITICAL", "HIGH", "MEDIUM", "LOW", "INFO")),
            "state" to mapOf("type" to "string", "enum" to listOf("OPEN", "RESOLVED")),
            "search" to mapOf("type" to "string", "maxLength" to 200),
        ),
    )

    override suspend fun execute(arguments: Map<String, Any>, context: McpExecutionContext): McpToolResult {
        requireDelegation(context)?.let { return it }
        if (!context.hasPermission(McpPermission.INTEGRATIONS_READ))
            return McpToolResult.error("FORBIDDEN", "Integration read permission required")
        val (page, size) = page(arguments)
        val filter = IntegrationFindingFilter(
            scannerId = id(arguments, "scannerId"),
            subjectId = id(arguments, "subjectId"),
            githubRepositoryId = id(arguments, "githubRepositoryId"),
            source = arguments["source"] as? String,
            owner = arguments["owner"] as? String,
            severity = arguments["severity"] as? String,
            state = arguments["state"] as? String,
            search = arguments["search"] as? String,
        )
        return integrationRead(users, context) { reads.findings(page, size, filter, it) }
    }
}

/** Resolves one integration finding without bypassing delegated asset access. */
@Singleton
class GetIntegrationFindingTool(
    private val reads: IntegrationReadService,
    private val users: UserRepository,
) : McpTool {
    override val name = "get_integration_finding"
    override val description = "Get one asset-scoped scanner finding by its SecMan identifier."
    override val operation = McpOperation.READ
    override val inputSchema = idSchema

    override suspend fun execute(arguments: Map<String, Any>, context: McpExecutionContext): McpToolResult {
        requireDelegation(context)?.let { return it }
        if (!context.hasPermission(McpPermission.INTEGRATIONS_READ))
            return McpToolResult.error("FORBIDDEN", "Integration read permission required")
        val findingId = id(arguments) ?: return McpToolResult.error("VALIDATION_ERROR", "id is required")
        return integrationRead(users, context) { reads.finding(findingId, it) }
    }
}

/** Lists historical integration runs visible to the delegated user. */
@Singleton
class ListIntegrationRunsTool(
    private val reads: IntegrationReadService,
    private val users: UserRepository,
) : McpTool {
    override val name = "list_integration_runs"
    override val description = "List asset-scoped scanner runs for operational and regression analysis."
    override val operation = McpOperation.READ
    override val inputSchema: Map<String, Any> = mapOf(
        "type" to "object",
        "properties" to pageProperties + mapOf(
            "scannerId" to mapOf("type" to "integer", "minimum" to 1),
            "subjectId" to mapOf("type" to "integer", "minimum" to 1),
        ),
    )

    override suspend fun execute(arguments: Map<String, Any>, context: McpExecutionContext): McpToolResult {
        requireDelegation(context)?.let { return it }
        if (!context.hasPermission(McpPermission.INTEGRATIONS_READ))
            return McpToolResult.error("FORBIDDEN", "Integration read permission required")
        val (page, size) = page(arguments)
        return integrationRead(users, context) {
            reads.runs(page, size, id(arguments, "scannerId"), id(arguments, "subjectId"), it)
        }
    }
}

/** Resolves one integration run together with its authorized finding snapshot. */
@Singleton
class GetIntegrationRunTool(
    private val reads: IntegrationReadService,
    private val users: UserRepository,
) : McpTool {
    override val name = "get_integration_run"
    override val description = "Get one asset-scoped scanner run with its historical finding snapshot."
    override val operation = McpOperation.READ
    override val inputSchema = idSchema

    override suspend fun execute(arguments: Map<String, Any>, context: McpExecutionContext): McpToolResult {
        requireDelegation(context)?.let { return it }
        if (!context.hasPermission(McpPermission.INTEGRATIONS_READ))
            return McpToolResult.error("FORBIDDEN", "Integration read permission required")
        val runId = id(arguments) ?: return McpToolResult.error("VALIDATION_ERROR", "id is required")
        return integrationRead(users, context) { reads.run(runId, it) }
    }
}
package com.secman.mcp

import com.secman.domain.McpPermission
import com.secman.domain.McpPermission.*

/**
 * Declarative tool -> permission mappings for MCP authorization.
 *
 * Both maps use "any of" semantics: a caller is authorized for a tool when its
 * effective permission set contains **at least one** of the permissions mapped to
 * that tool. A tool absent from a map is denied by that map.
 *
 * Two maps, deliberately, because the two gates have never been identical:
 *
 * - [LISTING] gates `tools/list` (via `McpToolRegistry.getAuthorizedTools`).
 * - [CALLING] gates `tools/call` (via `McpToolPermissionService.hasPermissionWithSet`).
 *
 * A tool must pass both to be usable end-to-end. They are colocated here so the
 * divergence is visible in one screen instead of spread over two 200-line `when`
 * blocks; the contents reproduce those blocks exactly.
 *
 * Coarse permission only — the fine-grained role check (ADMIN / VULN /
 * SECCHAMPION / ...) lives in each tool's `execute()`, see `McpToolGuards`.
 */
object McpToolPermissions {

    private fun table(vararg groups: Pair<Set<McpPermission>, List<String>>): Map<String, Set<McpPermission>> =
        groups.flatMap { (permissions, tools) -> tools.map { it to permissions } }.toMap()

    /**
     * Permissions required for a tool to appear in `tools/list`.
     *
     * Only names of registered tools appear here: `McpToolRegistry.isToolAuthorized`
     * resolves the tool first and denies unknown names before consulting this map,
     * so entries for tools that do not exist would be unreachable.
     *
     * `application_register` is intentionally absent — it has never been mapped.
     */
    val LISTING: Map<String, Set<McpPermission>> = table(
        setOf(INTEGRATIONS_WRITE) to listOf("submit_integration_run"),
        setOf(INTEGRATIONS_READ, ASSETS_READ, INTEGRATIONS_WRITE) to listOf("list_integration_subjects"),
        setOf(INTEGRATIONS_READ) to listOf(
            "get_integration_summary", "list_integration_findings", "get_integration_finding",
            "list_integration_runs", "get_integration_run",
        ),
        setOf(REQUIREMENTS_READ) to listOf(
            "get_requirements", "list_use_cases", "export_requirements",
            // Releases and alignment — ADMIN/RELEASE_MANAGER/REQ role checked in execute()
            "list_releases", "get_release", "compare_releases",
            "create_release", "delete_release", "set_release_status",
            "start_alignment", "submit_review", "get_alignment_status", "finalize_alignment",
        ),
        setOf(REQUIREMENTS_WRITE) to listOf(
            "add_requirement", "update_requirement", "set_requirement_use_cases",
            "create_use_case", "update_use_case",
            "delete_all_requirements", // ADMIN role also checked in execute()
        ),
        setOf(REQUIREMENTS_DELETE) to listOf("delete_requirement", "delete_use_case"),
        setOf(ASSESSMENTS_READ) to listOf(
            "list_aws_account_risk_assessments", // ADMIN role checked in execute()
            "list_risk_assessments", "get_risk_assessment_questionnaire", "get_risk_assessment_answers",
            "evaluate_risk_assessment", "get_risk_assessment_statistics",
            // Read-only views of the onboarding rule set. ADMIN/SECCHAMPION checked in execute().
            "list_account_onboarding_rules", "preview_account_onboarding_rules",
        ),
        setOf(ASSESSMENTS_WRITE) to listOf("create_risk_assessment"),
        setOf(ASSESSMENTS_EXECUTE) to listOf("save_risk_assessment_answers", "submit_risk_assessment"),
        setOf(USER_ACTIVITY) to listOf(
            // ADMIN role checked in execute() for all of these
            "list_users", "add_user", "delete_user",
            "import_user_mappings", "list_user_mappings",
            "list_aws_account_sharing", "create_aws_account_sharing", "delete_aws_account_sharing",
            // Same group as import_user_mappings because it has the same side effect: it
            // onboards an account owner, mail included. ADMIN/SECCHAMPION checked in execute().
            "simulate_account_onboarding",
        ),
        setOf(ASSETS_READ) to listOf(
