            setOf(ASSESSMENTS_READ) to listOf(
                "list_aws_account_risk_assessments",
                "list_risk_assessments", "get_risk_assessment_questionnaire", "get_risk_assessment_answers",
                "evaluate_risk_assessment", "get_risk_assessment_statistics",
                "list_account_onboarding_rules", "preview_account_onboarding_rules",
            ),
            setOf(ASSESSMENTS_WRITE) to listOf("create_risk_assessment"),
            setOf(ASSESSMENTS_EXECUTE) to listOf("save_risk_assessment_answers", "submit_risk_assessment"),
            setOf(WORKGROUPS_WRITE) to listOf(
                "create_workgroup", "delete_workgroup",
                "assign_assets_to_workgroup", "assign_users_to_workgroup",
                // These six were in LISTING but absent here, so tools/call denied them
                // unconditionally — visible in tools/list yet uncallable. The same
                // fail-closed shape as the add_requirement bug noted above.
                "list_workgroup_aws_accounts", "add_workgroup_aws_account", "remove_workgroup_aws_account",
                "list_workgroup_ad_domains", "add_workgroup_ad_domain", "remove_workgroup_ad_domain",
                "link_workgroup_aws_accounts",
            ),
            setOf(NOTIFICATIONS_SEND) to listOf(
                "send_github_repo_alerts",
                // Same fail-closed gap: listed but never added to CALLING.
                "notify_new_accounts", "send_application_register_reminders",
                "send_exception_expiry_reminders", "send_outdated_notifications",
                "send_vulnerability_notifications",
                "notify_risk_assessment_respondent",
            ),
            setOf(SYSTEM_INFO) to listOf("get_secman_statistics"),
        ))

        ToolCategories.CATEGORY_PERMISSIONS.reversed().forEach { (tools, unlocking) ->
            tools.forEach { put(it, unlocking) }
        }
    }

    /** True when [permissions] satisfies the "any of" requirement recorded in [table]. */
    fun allows(table: Map<String, Set<McpPermission>>, toolName: String, permissions: Set<McpPermission>): Boolean =
        table[toolName]?.any { it in permissions } == true
}
package com.secman.mcp.tools

import com.secman.dto.mcp.McpExecutionContext

/**
 * Shared guard helpers for MCP tool `execute()` preambles.
 *
 * Each returns an [McpToolResult.Error] when the precondition fails, or null when
 * execution may proceed — use as:
 *
 *     requireDelegation(context)?.let { return it }
 *
 * The error codes and messages are the exact strings the tools have always
 * returned; MCP clients and E2E scripts match on them, so never reword here and
 * always pass the caller's own `code`/`message` where the tool had one.
 */

/** Gate for tools that require User Delegation (audit trail). */
fun requireDelegation(context: McpExecutionContext): McpToolResult.Error? =
    if (!context.hasDelegation()) {
        McpToolResult.Error(
            "DELEGATION_REQUIRED",
            "User Delegation must be enabled to use this tool"
        )
    } else null

/**
 * Gate for tools restricted to specific delegated-user roles. Admin API keys
 * always pass; otherwise at least one of [roles] must be present on the
 * delegated user.
 */
fun requireAnyRole(
    context: McpExecutionContext,
    vararg roles: String,
    code: String = "FORBIDDEN",
    message: String = "Insufficient role to use this tool"
): McpToolResult.Error? =
    if (context.isAdmin || roles.any { context.delegatedUserRoles?.contains(it) == true }) {
        null
    } else {
        McpToolResult.Error(code, message)
    }

/**
 * Gate that looks **only** at the delegated user's own roles — unlike
 * [requireAnyRole] an admin API key does not bypass it, so "ADMIN" has to be
 * listed explicitly when it should grant access. Role names are compared
 * case-insensitively.
 */
fun requireAnyUserRole(
    context: McpExecutionContext,
    vararg roles: String,
    code: String = "AUTHORIZATION_ERROR",
    message: String
): McpToolResult.Error? {
    val held = context.delegatedUserRoles?.mapTo(mutableSetOf()) { it.uppercase() } ?: emptySet<String>()
    return if (roles.any { it.uppercase() in held }) null else McpToolResult.Error(code, message)
}

