  useEffect(() => {
    let active = true;
    setExposures(null);
    getWebExposures(exposurePage)
      .then((value) => { if (active) setExposures(value); })
      .catch((reason) => {
        if (active) setError(reason instanceof Error ? reason.message : 'Could not load scanned assets.');
