                    <td><a href={`/assets/${component.assetId}`}>{component.assetName}</a></td>
                    <td>{Math.round(component.confidence * 100)}%</td>
                    <td>{formatServerDate(component.lastSeenAt)}</td>
                  </tr>
                ))}
