              </tbody>
            </table>
          </div>
          <Pagination currentPage={componentPage} totalPages={components.totalPages} totalElements={components.totalElements} pageSize={PAGE_SIZE} onPageChange={setComponentPage} />
        </>
      )}
    </section>
  );
