package com.secman.service

import com.fasterxml.jackson.databind.ObjectMapper
import com.secman.dto.*
import io.micronaut.http.HttpStatus
import io.micronaut.http.exceptions.HttpStatusException
import jakarta.inject.Singleton
import java.io.ByteArrayInputStream
import java.io.ByteArrayOutputStream
import java.net.URI
import java.nio.charset.CodingErrorAction
import java.security.MessageDigest
import java.time.Instant
import java.util.Base64
import javax.imageio.ImageIO

data class ValidatedIntegrationAttachment(val fileName: String, val contentType: String, val bytes: ByteArray, val decodedSize: Int = bytes.size)
data class ValidatedIntegrationRun(
    val request: IntegrationRunRequest, val digest: String, val findingsJson: String,
    val inventoryJson: String, val attachments: List<List<ValidatedIntegrationAttachment>>
)

object IntegrationLifecycle {
    fun resolvesAbsent(run: IntegrationRunRequest) = run.status == "SUCCESS" && run.completeCoverage
    fun isNewer(run: IntegrationRunRequest, lastScanAt: Instant?) = lastScanAt == null || run.completedAt > lastScanAt
}

@Singleton
class IntegrationRunValidator(private val mapper: ObjectMapper) {
    companion object {
        val STATUSES = setOf("SUCCESS", "PARTIAL", "FAILED", "SKIPPED")
        val SEVERITIES = setOf("CRITICAL", "HIGH", "MEDIUM", "LOW", "INFO")
        val SOURCES = setOf("GITHUB_AI", "VISUAL", "WEB_SECURITY")
        val COMPONENT_CATEGORIES = setOf("JAVASCRIPT_LIBRARY", "CSS_LIBRARY", "WEB_SERVER")
        val REACHABILITY = setOf("REACHABLE", "UNREACHABLE", "UNKNOWN")
        val EVIDENCE_TYPES = setOf("RESOURCE_URL", "HTTP_HEADER")
        const val MAX_ATTACHMENT_BYTES = 1024 * 1024
        const val MAX_RUN_BYTES = 5 * MAX_ATTACHMENT_BYTES
    }

    fun validate(request: IntegrationRunRequest, now: Instant = Instant.now()): ValidatedIntegrationRun {
        check(request.scannerId > 0 && request.subjectId > 0, "Invalid scanner or subject")
        text(request.runKey, 128, true)
        check(request.runKey.matches(Regex("[A-Za-z0-9._:/-]+")), "Invalid run key")
        check(request.status in STATUSES, "Invalid status")
        check(request.startedAt >= Instant.parse("2000-01-01T00:00:00Z") &&
            request.startedAt <= request.completedAt && request.completedAt <= now.plusSeconds(300), "Invalid timestamps")
        check(request.findings.size <= 500, "At most 500 findings are allowed")
        check(request.findings.map { it.externalId }.toSet().size == request.findings.size, "Duplicate external IDs")
        text(request.metadataJson, 16000)
        check(parseJson(request.metadataJson).isObject, "metadataJson must be an object")
        var total = 0L
        val attachments = request.findings.map { finding ->
            validateFinding(finding)
            total += listOfNotNull(finding.description, finding.recommendation, finding.evidence).sumOf { it.toByteArray().size.toLong() }
            finding.attachments.map {
                val attachment = validateAttachment(it)
                total += maxOf(attachment.decodedSize, attachment.bytes.size)
                check(total <= MAX_RUN_BYTES, "Evidence exceeds 5 MiB")
                attachment
            }
        }
        total += request.inventory?.let(::validateInventory) ?: 0
        check(total <= MAX_RUN_BYTES, "Evidence exceeds 5 MiB")
        // Hash the fixed DTO representation, so HTTP and MCP retries share a digest.
        val digest = MessageDigest.getInstance("SHA-256").digest(mapper.writeValueAsBytes(request))
            .joinToString("") { "%02x".format(it) }
        return ValidatedIntegrationRun(
            request,
            digest,
            mapper.writeValueAsString(request.findings.map { it.copy(attachments = emptyList()) }),
            mapper.writeValueAsString(request.inventory),
            attachments
        )
    }

    private fun validateInventory(inventory: WebInventoryInput): Long {
        check(inventory.components.size <= 500, "At most 500 components are allowed")
        check(inventory.components.map { it.componentKey }.toSet().size == inventory.components.size,
            "Duplicate component keys")
        inventory.exposure?.let { exposure ->
            inventoryUrl(exposure.configuredUrl, true)
            inventoryUrl(exposure.effectiveUrl)
            check(exposure.reachability in REACHABILITY, "Invalid reachability")
            check(exposure.httpStatus == null || exposure.httpStatus in 100..599, "Invalid HTTP status")
            check(exposure.redirectCount in 0..20, "Invalid redirect count")
            text(exposure.vantagePoint, 100, true)
            check(exposure.vantagePoint.matches(Regex("[A-Za-z0-9._:-]+")), "Invalid vantage point")
        }
        inventory.components.forEach { component ->
            text(component.componentKey, 128, true)
            check(component.componentKey.matches(Regex("[A-Za-z0-9._:-]+")), "Invalid component key")
            check(component.category in COMPONENT_CATEGORIES, "Invalid component category")
            text(component.name, 255, true)
            text(component.version, 100)
            check(component.confidence.isFinite() && component.confidence in 0.0..1.0,
                "Invalid component confidence")
            check(component.evidenceType in EVIDENCE_TYPES, "Invalid component evidence type")
            text(component.evidence, 512, true)
            inventoryUrl(component.sourceUrl)
        }
        return mapper.writeValueAsBytes(inventory).size.toLong()
    }

    private fun inventoryUrl(value: String?, required: Boolean = false) {
        text(value, 2048, required)
        if (value == null) return
        val uri = try { URI(value) } catch (_: Exception) { invalid("Invalid inventory URL") }
        check(uri.scheme in setOf("https", "http") && !uri.host.isNullOrBlank() &&
            uri.userInfo == null && uri.rawQuery == null && uri.rawFragment == null,
            "Invalid inventory URL")
    }

    private fun validateFinding(f: IntegrationFindingInput) {
        text(f.externalId, 200, true)
        check(f.severity in SEVERITIES, "Invalid severity")
        text(f.title, 500, true)
        listOf(f.description, f.recommendation, f.evidence).forEach { text(it, 16000) }
        text(f.filePath, 1024); text(f.lineRange, 100); text(f.engine, 100); text(f.model, 200)
        text(f.commitSha, 64)
        listOf(f.url, f.issueUrl, f.fixPrUrl).forEach { url ->
            text(url, 2048)
            if (url != null) {
                val uri = try { URI(url) } catch (_: Exception) { invalid("Invalid URL") }
                check(uri.scheme in setOf("https", "http") && !uri.host.isNullOrBlank() && uri.userInfo == null, "Invalid URL")
            }
        }
        check(f.confidence == null || (f.confidence.isFinite() && f.confidence in 0.0..1.0), "Invalid confidence")
        check(f.legacyIds.size <= 10 && f.legacyIds.toSet().size == f.legacyIds.size, "Invalid legacy IDs")
        f.legacyIds.forEach { text(it, 255, true) }
        check(f.attachments.size <= 10, "At most 10 attachments per finding")
    }

    private fun validateAttachment(input: IntegrationAttachmentInput): ValidatedIntegrationAttachment {
        text(input.fileName, 200, true)
        check(input.fileName.matches(Regex("[A-Za-z0-9][A-Za-z0-9._ -]*")) && !input.fileName.contains(".."), "Invalid file name")
        val extensions = mapOf("image/png" to setOf("png"), "image/jpeg" to setOf("jpg", "jpeg"),
            "text/plain" to setOf("txt"), "application/json" to setOf("json"))
        check(input.fileName.substringAfterLast('.').lowercase() in (extensions[input.contentType] ?: emptySet()), "Invalid attachment type")
        check(input.base64.length <= ((MAX_ATTACHMENT_BYTES + 2) / 3) * 4, "Attachment exceeds 1 MiB")
        val bytes = try { Base64.getDecoder().decode(input.base64) } catch (_: IllegalArgumentException) { invalid("Invalid base64") }
        check(bytes.isNotEmpty() && bytes.size <= MAX_ATTACHMENT_BYTES, "Invalid attachment size")
        val safeBytes = if (input.contentType.startsWith("image/")) sanitizeImage(bytes, input.contentType) else {
            val decoded = try {
                Charsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT)
                    .decode(java.nio.ByteBuffer.wrap(bytes)).toString()
            } catch (_: Exception) { invalid("Attachment must be UTF-8") }
            check(decoded.none { it == '\u0000' }, "Invalid text attachment")
            if (input.contentType == "application/json") parseJson(decoded)
            bytes
        }
        check(safeBytes.size <= MAX_ATTACHMENT_BYTES, "Attachment exceeds 1 MiB after normalization")
        return ValidatedIntegrationAttachment(input.fileName, input.contentType, safeBytes, bytes.size)
    }

    private fun sanitizeImage(bytes: ByteArray, contentType: String): ByteArray {
        try {
            ImageIO.createImageInputStream(ByteArrayInputStream(bytes)).use { stream ->
                val readers = ImageIO.getImageReaders(stream)
                check(readers.hasNext(), "Invalid image")
                val reader = readers.next()
                try {
                    reader.input = stream
                    val format = reader.formatName.lowercase()
                    check(if (contentType == "image/png") format == "png" else format in setOf("jpeg", "jpg"), "Image type mismatch")
                    val width = reader.getWidth(0)
                    val height = reader.getHeight(0)
                    check(width in 1..8192 && height in 1..8192 && width.toLong() * height <= 16_000_000, "Image dimensions exceed limit")
                    val output = ByteArrayOutputStream()
                    check(ImageIO.write(reader.read(0), format, output), "Unsupported image")
                    return output.toByteArray()
                } finally { reader.dispose() }
            }
        } catch (e: HttpStatusException) { throw e
        } catch (_: Exception) { invalid("Invalid image") }
    }

    private fun parseJson(value: String): com.fasterxml.jackson.databind.JsonNode = try {
        mapper.readerFor(com.fasterxml.jackson.databind.JsonNode::class.java)
            .with(com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS)
            .readValue<com.fasterxml.jackson.databind.JsonNode>(value) ?: invalid("Invalid JSON")
    } catch (_: com.fasterxml.jackson.core.JsonProcessingException) { invalid("Invalid JSON") }

    private fun text(value: String?, max: Int, required: Boolean = false) {
        check(!required || !value.isNullOrBlank(), "Required text is missing")
        check(value == null || (value.length <= max && value.none { it == '\u0000' }), "Text exceeds limit or contains invalid characters")
    }
    private fun check(condition: Boolean, message: String) { if (!condition) invalid(message) }
    private fun invalid(message: String): Nothing = throw HttpStatusException(HttpStatus.BAD_REQUEST, message)
}
package com.secman.controller

import com.secman.dto.*
import com.secman.service.*
import io.micronaut.core.annotation.Nullable
import io.micronaut.http.HttpResponse
import io.micronaut.http.annotation.*
import io.micronaut.scheduling.TaskExecutors
import io.micronaut.scheduling.annotation.ExecuteOn
import io.micronaut.security.annotation.Secured
import io.micronaut.security.authentication.Authentication
import io.micronaut.security.rules.SecurityRule

@Controller("/api/integrations/v1")
@Secured(SecurityRule.IS_AUTHENTICATED)
@ExecuteOn(TaskExecutors.BLOCKING)
open class IntegrationController(
    private val admin: IntegrationAdminService,
    private val reads: IntegrationReadService,
    private val scans: IntegrationScanService,
    private val health: IntegrationHealthNotifier
) {
    @Get("/scanners")
    open fun scanners(authentication: Authentication) = reads.scanners(authentication)

    @Post("/scanners")
    @Secured("ADMIN")
    open fun createScanner(@Body request: IntegrationScannerRequest, authentication: Authentication) =
        admin.saveScanner(null, request, authentication)

    @Put("/scanners/{id}")
    @Secured("ADMIN")
    open fun updateScanner(@PathVariable id: Long, @Body request: IntegrationScannerRequest, authentication: Authentication) =
        admin.saveScanner(id, request, authentication)

    @Post("/scanners/{id}/subjects")
    @Secured("ADMIN")
    open fun bind(@PathVariable id: Long, @Body request: IntegrationSubjectRequest, authentication: Authentication) =
        reads.subject(admin.bind(id, request, authentication), authentication)

    @Get("/scanners/{id}/subjects")
    open fun subjects(@PathVariable id: Long, @QueryValue(defaultValue = "0") page: Int,
                      @QueryValue(defaultValue = "100") size: Int, authentication: Authentication) =
        reads.subjects(id, page, size, authentication)

    @Post("/runs")
    open fun submit(@Body request: IntegrationRunRequest, authentication: Authentication) =
        scans.submit(request, authentication).also(health::completed)

    @Get("/summary")
    open fun summary(authentication: Authentication) = reads.summary(authentication)

    @Get("/web-exposure/summary")
    @Secured("ADMIN", "VULN", "SECCHAMPION")
    open fun webExposureSummary(authentication: Authentication) =
        reads.webExposureSummary(authentication)

    @Get("/web-exposures")
    @Secured("ADMIN", "VULN", "SECCHAMPION")
    open fun webExposures(
        @QueryValue(defaultValue = "0") page: Int,
        @QueryValue(defaultValue = "100") size: Int,
        @Nullable @QueryValue reachability: String?,
        authentication: Authentication
    ) = reads.webExposures(page, size, WebExposureFilter(reachability), authentication)

    @Get("/web-components")
    @Secured("ADMIN", "VULN", "SECCHAMPION")
    open fun webComponents(
        @QueryValue(defaultValue = "0") page: Int,
        @QueryValue(defaultValue = "100") size: Int,
        @Nullable @QueryValue category: String?,
        @Nullable @QueryValue(defaultValue = "OPEN") state: String?,
        @Nullable @QueryValue search: String?,
        authentication: Authentication
    ) = reads.webComponents(page, size, WebComponentFilter(category, state, search), authentication)

    @Get("/runs/{id}")
    open fun run(@PathVariable id: Long, authentication: Authentication) = reads.run(id, authentication)

    @Get("/runs")
    open fun runs(@QueryValue(defaultValue = "0") page: Int, @QueryValue(defaultValue = "100") size: Int,
                  @Nullable @QueryValue scannerId: Long?, @Nullable @QueryValue subjectId: Long?, authentication: Authentication) =
        reads.runs(page, size, scannerId, subjectId, authentication)

    @Get("/findings")
    open fun findings(@QueryValue(defaultValue = "0") page: Int, @QueryValue(defaultValue = "100") size: Int,
                      @Nullable @QueryValue scannerId: Long?, @Nullable @QueryValue subjectId: Long?,
                      @Nullable @QueryValue githubRepositoryId: Long?, @Nullable @QueryValue source: String?,
                      @Nullable @QueryValue owner: String?, @Nullable @QueryValue severity: String?,
                      @Nullable @QueryValue state: String?, @Nullable @QueryValue search: String?, authentication: Authentication) =
        reads.findings(page, size, IntegrationFindingFilter(scannerId, subjectId, githubRepositoryId, source, owner, severity, state, search), authentication)

    @Get("/findings/{id}")
    open fun finding(@PathVariable id: Long, authentication: Authentication) = reads.finding(id, authentication)

    @Get("/findings/{id}/attachments/{attachmentId}")
    open fun attachment(@PathVariable id: Long, @PathVariable attachmentId: Long, authentication: Authentication): HttpResponse<ByteArray> {
        val attachment = reads.attachment(id, attachmentId, authentication)
        return HttpResponse.ok(attachment.content).contentType(attachment.contentType)
            .header("X-Content-Type-Options", "nosniff")
            .header("Content-Disposition", "attachment; filename=\"" + attachment.fileName + "\"")
            .header("Cache-Control", "private, no-store")
    }
}
package com.secman.repository

import com.secman.domain.*
import com.secman.dto.IntegrationPage
import jakarta.inject.Singleton
import jakarta.persistence.EntityManager
import jakarta.persistence.LockModeType
import java.time.Instant

/** Persistence operations used inside the integration services' transactions. */
@Singleton
class IntegrationRepository(private val em: EntityManager) {
    fun <T : Any> findMany(type: Class<T>, ids: Collection<Long>): List<T> {
        if (ids.isEmpty()) return emptyList()
        val sql = when (type) {
            Asset::class.java -> "FROM Asset x WHERE x.id IN :ids"
            IntegrationScanner::class.java -> "FROM IntegrationScanner x WHERE x.id IN :ids"
            IntegrationSubject::class.java -> "FROM IntegrationSubject x WHERE x.id IN :ids"
            GithubRepository::class.java -> "FROM GithubRepository x WHERE x.id IN :ids"
            Vulnerability::class.java -> "FROM Vulnerability x WHERE x.id IN :ids"
            else -> error("Unsupported integration lookup")
        }
        return em.createQuery(sql, type).setParameter("ids", ids).resultList
    }
    fun attachmentMetadata(findingIds: Collection<Long>): List<Array<Any>> {
        if (findingIds.isEmpty()) return emptyList()
        @Suppress("UNCHECKED_CAST")
        return em.createQuery("SELECT a.findingId, a.id, a.fileName, a.contentType FROM IntegrationAttachment a, IntegrationFinding f WHERE a.findingId = f.id AND a.runId = f.lastRunId AND f.id IN :ids ORDER BY a.id")
            .setParameter("ids", findingIds).resultList as List<Array<Any>>
    }
    fun runAttachmentMetadata(runId: Long): List<Array<Any>> {
        @Suppress("UNCHECKED_CAST")
        return em.createQuery("SELECT a.id, a.findingId, a.fileName, a.contentType FROM IntegrationAttachment a WHERE a.runId = :run ORDER BY a.id")
            .setParameter("run", runId).setMaxResults(5000).resultList as List<Array<Any>>
    }
    fun openCounts(subjectIds: Collection<Long>): Map<Long, Long> {
        if (subjectIds.isEmpty()) return emptyMap()
        return em.createQuery("SELECT f.subjectId, COUNT(f) FROM IntegrationFinding f WHERE f.subjectId IN :ids AND f.state = 'OPEN' GROUP BY f.subjectId")
            .setParameter("ids", subjectIds).resultList.associate { row ->
                val values = row as Array<*>
                (values[0] as Long) to (values[1] as Long)
            }
    }
    fun <T : Any> find(type: Class<T>, id: Long): T? = em.find(type, id)
    fun <T : Any> lock(type: Class<T>, id: Long): T? = em.find(type, id, LockModeType.PESSIMISTIC_WRITE)
    fun scannerForSubmission(id: Long): IntegrationScanner? =
        em.find(IntegrationScanner::class.java, id, LockModeType.PESSIMISTIC_READ)
    fun persist(entity: Any) { em.persist(entity) }
    fun remove(entity: Any) { em.remove(entity) }
    fun flush() { em.flush() }

    fun replay(scannerId: Long, subjectId: Long, key: String): IntegrationRun? =
        em.createQuery("FROM IntegrationRun r WHERE r.scannerId = :scanner AND r.subjectId = :subject AND r.runKey = :key", IntegrationRun::class.java)
            .setParameter("scanner", scannerId).setParameter("subject", subjectId).setParameter("key", key).resultList.singleOrNull()

    fun finding(subjectId: Long, externalId: String): IntegrationFinding? =
        em.createQuery("FROM IntegrationFinding f WHERE f.subjectId = :subject AND f.externalId = :external", IntegrationFinding::class.java)
            .setParameter("subject", subjectId).setParameter("external", externalId).resultList.singleOrNull()

    fun webExposure(subjectId: Long): WebExposure? =
        em.createQuery("FROM WebExposure x WHERE x.subjectId = :subject", WebExposure::class.java)
            .setParameter("subject", subjectId).resultList.singleOrNull()

    fun webComponent(subjectId: Long, componentKey: String): WebComponent? =
        em.createQuery("FROM WebComponent x WHERE x.subjectId = :subject AND x.componentKey = :key", WebComponent::class.java)
            .setParameter("subject", subjectId).setParameter("key", componentKey).resultList.singleOrNull()

    fun openFindingPage(subjectId: Long, afterId: Long): List<IntegrationFinding> =
        em.createQuery("FROM IntegrationFinding f WHERE f.subjectId = :subject AND f.state = 'OPEN' AND f.id > :after ORDER BY f.id", IntegrationFinding::class.java)
            .setParameter("subject", subjectId).setParameter("after", afterId).setMaxResults(500).resultList

    fun openWebComponentPage(subjectId: Long, afterId: Long): List<WebComponent> =
        em.createQuery("FROM WebComponent x WHERE x.subjectId = :subject AND x.state = 'OPEN' AND x.id > :after ORDER BY x.id", WebComponent::class.java)
            .setParameter("subject", subjectId).setParameter("after", afterId).setMaxResults(500).resultList

    fun legacyCandidates(assetId: Long, legacyIds: List<String>): List<Vulnerability> =
        if (legacyIds.isEmpty()) emptyList() else em.createQuery(
            "FROM Vulnerability v WHERE v.asset.id = :asset AND v.vulnerabilityId IN :ids", Vulnerability::class.java
        ).setParameter("asset", assetId).setParameter("ids", legacyIds).setMaxResults(11).resultList

    fun projectionClaimed(id: Long): Boolean = em.createQuery(
        "SELECT COUNT(f) FROM IntegrationFinding f WHERE f.vulnerabilityId = :id", Long::class.javaObjectType
    ).setParameter("id", id).singleResult > 0

    fun legacyIdentityClaimed(assetId: Long, ids: List<String>): Boolean =
        if (ids.isEmpty()) false else em.createQuery(
            "SELECT COUNT(f) FROM IntegrationFinding f, IntegrationSubject s WHERE f.subjectId = s.id AND s.assetId = :asset AND f.projectionKey IN :ids",
            Long::class.javaObjectType
        ).setParameter("asset", assetId).setParameter("ids", ids).singleResult > 0

    fun attachments(findingId: Long, runId: Long): List<IntegrationAttachment> = em.createQuery(
        "FROM IntegrationAttachment a WHERE a.findingId = :finding AND a.runId = :run ORDER BY a.id", IntegrationAttachment::class.java
    ).setParameter("finding", findingId).setParameter("run", runId).setMaxResults(10).resultList

    fun <T : Any> page(type: Class<T>, template: IntegrationPageQuery, params: Map<String, Any?>, page: Int, size: Int): IntegrationPage<T> {
        require(page in 0..100000 && size in 1..100) { "Invalid pagination" }
        val query = em.createQuery(template.select, type)
        val count = em.createQuery(template.count, Long::class.javaObjectType)
        params.forEach { (name, value) -> query.setParameter(name, value); count.setParameter(name, value) }
        val total = count.singleResult
        return IntegrationPage(query.setFirstResult(page * size).setMaxResults(size).resultList,
            total, ((total + size - 1) / size).toInt(), page, size)
    }

    fun count(template: IntegrationCountQuery, assetIds: Set<Long>?): Long {
        val query = em.createQuery(template.sql, Long::class.javaObjectType)
            .setParameter("unscoped", assetIds == null).setParameter("assets", assetIds?.ifEmpty { setOf(-1L) } ?: setOf(-1L))
        if (template in setOf(IntegrationCountQuery.HEALTHY, IntegrationCountQuery.STALE)) query.setParameter("now", java.time.Instant.now())
        return query.singleResult
    }

    fun latestWebExposure(assetIds: Set<Long>): Instant? {
        if (assetIds.isEmpty()) return null
        return em.createQuery(
            "SELECT MAX(x.observedAt) FROM WebExposure x, IntegrationSubject s WHERE x.subjectId = s.id AND s.assetId IN :assets",
            Instant::class.java
        ).setParameter("assets", assetIds).singleResult
    }

    fun boundSubject(scannerId: Long, assetId: Long): IntegrationSubject? = em.createQuery(
        "FROM IntegrationSubject s WHERE s.scannerId = :scanner AND s.assetId = :asset", IntegrationSubject::class.java
    ).setParameter("scanner", scannerId).setParameter("asset", assetId).resultList.singleOrNull()

    fun repositorySubject(repositoryId: Long): IntegrationSubject? = em.createQuery(
        "FROM IntegrationSubject s WHERE s.githubRepositoryId = :repo ORDER BY s.id", IntegrationSubject::class.java
    ).setParameter("repo", repositoryId).setMaxResults(1).resultList.firstOrNull()

    fun legacyAssets(name: String): List<Asset> = em.createQuery(
        "FROM Asset a WHERE a.name = :name", Asset::class.java
    ).setParameter("name", name).setMaxResults(2).resultList
}

